struct Circle {
    radius: f64,
}

impl Circle {
    fn area(&self) -> f64 {
        std::f64::consts::PI * self.radius * self.radius
    }
}

fn describe(n: Option<i32>) -> &'static str {
    match n {
        Some(x) if x < 0 => "negative",
        Some(0) => "zero",
        Some(_) => "positive",
        None => "nothing",
    }
}

trait Speak {
